#!/usr/bin/env python3
"""Generate standalone launchers from the only editable source tree."""
import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generated_files():
    support = (ROOT / "src/netpulse/features.py").read_text()
    prefix = ("#!/usr/bin/env python3\n"
              "# Generated by tools/build_executables.py; edit src/netpulse/ instead.\n"
              "import sys as _sys, types as _types\n"
              "_features = _types.ModuleType('netpulse.features')\n"
              "_sys.modules['netpulse.features'] = _features\n"
              f"exec(compile({support!r}, '<netpulse.features>', 'exec'), _features.__dict__)\n")
    result = {}
    for source, target in (("gui.py", "netpulse-gui"), ("monitor.py", "netpulse-monitor")):
        body = (ROOT / "src/netpulse" / source).read_text()
        result[target] = (prefix + "\n" + "\n".join(body.splitlines()[2:]) + "\n").encode()
    result["netpulse-ctl"] = (ROOT / "src/netpulse/ctl.sh").read_bytes()
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="Fail if committed executables differ from sources.")
    args = parser.parse_args()
    stale = []
    for name, content in generated_files().items():
        path = ROOT / "bin" / name
        if args.check:
            if not path.exists() or path.read_bytes() != content:
                stale.append(name)
        else:
            path.write_bytes(content)
            path.chmod(0o755)
    if stale:
        print("Regenerate bin/: " + ", ".join(stale), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
